// Parse Claude's JSON response
const response = $input.first().json;
let parsed;
try {
  // Extract JSON from Claude response
  const text = response.message?.content?.[0]?.text || response.text || JSON.stringify(response);
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch[0]);
} catch (e) {
  parsed = { error: 'Parse failed', raw: JSON.stringify(response) };
}

return [{ json: parsed }];

// ============================================
// BUSINESS RULES - EDIT THESE TO MATCH YOUR CRITERIA
// ============================================

const RULES = {
  min_pay_rate: 40,        // Minimum $/hr to auto-accept
  request_min_rate: 25,    // Minimum $/hr to request (with counter-offer)
  max_travel_miles: 50,    // Maximum travel distance
  high_pay_override: 60,   // Override travel limit if pay >= this
  skip_work_types: ['Survey', 'Delivery'],
  counter_offer_rate: 50,  // Rate to counter-offer at
};

const job = $input.first().json;

if (job.error) {
  return [{ json: { decision: 'MANUAL_REVIEW', reason: 'Parse failed', ...job } }];
}

const payAmount = job.pay_amount || 0;
const distance = job.distance_miles || 0;
const workType = job.work_type || 'Other';

// Rule 1: Skip blacklisted work types
if (RULES.skip_work_types.includes(workType)) {
  return [{ json: { decision: 'SKIP', reason: `Work type ${workType} is blacklisted`, ...job } }];
}

// Rule 2: Skip if too far (unless high pay)
if (distance > RULES.max_travel_miles && payAmount < RULES.high_pay_override) {
  return [{ json: { decision: 'SKIP', reason: `Distance ${distance}mi exceeds ${RULES.max_travel_miles}mi limit`, ...job } }];
}

// Rule 3: Auto-accept if pay meets threshold
if (payAmount >= RULES.min_pay_rate) {
  return [{ json: { decision: 'ACCEPT', reason: `Pay $${payAmount}/hr meets $${RULES.min_pay_rate} minimum`, ...job } }];
}

// Rule 4: Request with counter-offer if pay is in range
if (payAmount >= RULES.request_min_rate && job.counter_offer_allowed) {
  return [{ json: { decision: 'REQUEST', reason: `Pay $${payAmount}/hr below threshold, counter-offer at $${RULES.counter_offer_rate}/hr`, counter_offer: RULES.counter_offer_rate, ...job } }];
}

// Rule 5: Skip if below request threshold
if (payAmount < RULES.request_min_rate) {
  return [{ json: { decision: 'SKIP', reason: `Pay $${payAmount}/hr below $${RULES.request_min_rate} minimum`, ...job } }];
}

// Default: manual review
return [{ json: { decision: 'MANUAL_REVIEW', reason: 'No rule matched', ...job } }];
